layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 3px solid var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 700; font-style: normal; line-height: 1.45; letter-spacing: -0.22px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 0px; padding-bottom: 4px; padding-left: 28px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: rgb(168, 159, 147); border-top: 1px solid var(--ryt-border); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-top: 1px solid var(--ryt-border); border-radius: 0px; transition: all; border-right: none; border-bottom: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: 1px; text-underline-offset: 3px; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 900; font-style: normal; line-height: 0.95; letter-spacing: -3.84px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: rgb(168, 159, 147); font-family: var(--ryt-font-heading); font-size: 13px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(168, 159, 147); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: rgb(168, 159, 147); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 700; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(168, 159, 147); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: rgb(168, 159, 147); font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 400; font-style: normal; line-height: 1.55; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(168, 159, 147); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-top: 1px solid var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-right: none; border-bottom: none; border-left: none }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 800; font-style: normal; line-height: 1.2; letter-spacing: -0.36px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #e8b04b }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #e8b04b; color: inherit }
[data-ryt="nav"] a:hover { color: #e8b04b }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #e8b04b; text-decoration-thickness: 2px }
article[data-ryt="rec-card"]:hover { color: #e8b04b; color: inherit }
